#[cfg(test)]
mod report_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_report_codec() {
        let original = Report {
            pbu: "a".repeat(8),
            set_id: 123456,
            report_index: 123456789,
            biz_id: 123456,
            exec_type: "a".to_string(),
            biz_pbu: "a".repeat(8),
            cl_ord_id: "a".repeat(10),
            security_id: "a".repeat(12),
            account: "a".repeat(13),
            owner_type: 42,
            order_entry_time: 123456789,
            last_px: -123456789,
            last_qty: -123456789,
            gross_trade_amt: -123456789,
            side: "a".to_string(),
            order_qty: -123456789,
            leaves_qty: -123456789,
            ord_status: "a".to_string(),
            credit_tag: "a".repeat(2),
            clearing_firm: "a".repeat(8),
            branch_id: "a".repeat(8),
            trd_cnfm_id: "a".repeat(16),
            ord_cnfm_id: "a".repeat(16),
            trade_date: 123456,
            transact_time: 123456789,
            user_info: "a".repeat(32),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(ReportRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        Report::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = Report::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

